import random

def get_user_choice():
    """Get user's choice (rock, paper, scissors)"""
    choices = ["rock", "paper", "scissors"]
    while True:
        user_choice = input("Enter your choice (rock, paper, scissors): ").lower()
        if user_choice in choices:
            return user_choice
        else:
            print("Invalid input. Please enter a valid choice.")

def get_computer_choice():
    """Get computer's choice (randomly)"""
    return random.choice(["rock", "paper", "scissors"])

def play_round(user_choice, computer_choice):
    """Play one round of Rock, Paper, Scissors and return the winner"""
    user_score = 0
    computer_score = 0

    if user_choice == computer_choice:
        print(f"It's a tie! {user_choice} vs {computer_choice}")
    elif (user_choice == "rock" and computer_choice == "scissors") or \
         (user_choice == "paper" and computer_choice == "rock") or \
         (user_choice == "scissors" and computer_choice == "paper"):
        print(f"You win! {user_choice} vs {computer_choice}")
        user_score += 1
    else:
        print(f"Computer wins! {computer_choice} vs {user_choice}")
        computer_score += 1

    print(f"User score: {user_score}, Computer score: {computer_score}")
    return user_score, computer_score

def play_game():
    """Play the entire game of Rock, Paper, Scissors"""
    while True:
        user_choice = get_user_choice()
        computer_choice = get_computer_choice()
        user_score, computer_score = play_round(user_choice, computer_choice)

        if user_score > computer_score:
            print("Congratulations, you won the game!")
            break
        elif user_score < computer_score:
            print("Sorry, computer won the game.")
            break
        else:
            print("It's a tie. Let's play again!")

if __name__ == "__main__":
    play_game()
```

This program defines functions to get user and computer choices, play one round, and play the entire game. The `play_game` function calls these functions repeatedly until the user wins or the game ends in a tie.
